create table wksp_dtesc.sgt_ot (
    id                     number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment
    by 1 cache 20 noorder nocycle nokeep noscale not null enable,
    codigo                 varchar2(30 byte) not null enable,
    tipo_trabajo_id        number not null enable,
    estado_id              number not null enable,
    prioridad_id           number not null enable,
    titulo                 varchar2(255 byte) not null enable,
    descripcion            varchar2(2000 byte) not null enable,
    instrucciones_jefatura varchar2(1000 byte),
    reportado_por          varchar2(255 byte) not null enable,
    asignado_a             varchar2(255 byte),
    fecha_asignacion       timestamp(6),
    fecha_recepcion        timestamp(6) default systimestamp not null enable,
    fecha_actualizacion    timestamp(6),
    creado_por             varchar2(255 byte),
    creado_el              timestamp(6) default systimestamp,
    actualizado_por        varchar2(255 byte),
    actualizado_el         timestamp(6)
);

alter table wksp_dtesc.sgt_ot add constraint uq_sgt_ot_codigo unique ( codigo )
    using index enable;

alter table wksp_dtesc.sgt_ot add primary key ( id )
    using index enable;


